const $=selector=>document.querySelector(selector);
const icons={box:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m12 3 9 5v8l-9 5-9-5V8l9-5Zm0 9 9-4M12 12 3 8m9 4v9M7.5 5.5l9 5"/></svg>',search:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>',check:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><circle cx="12" cy="12" r="9"/><path d="m8 12 3 3 5-6"/></svg>',price:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><path d="m3 12 9-9h8v8l-9 9-8-8Z"/><circle cx="16" cy="7" r="1"/></svg>',draft:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5"><rect x="5" y="3" width="14" height="18" rx="2"/><path d="M9 8h6m-6 4h6m-6 4h4"/></svg>'};
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const convertedAmount=(amount,currency)=>{const zero=['BIF','CLP','DJF','GNF','JPY','KMF','KRW','MGA','PYG','RWF','VND','VUV','XAF','XOF','XPF'];const three=['BHD','JOD','KWD','OMR','TND'];return new Intl.NumberFormat('en-GB',{style:'currency',currency}).format(amount/(zero.includes(currency)?1:three.includes(currency)?1000:100));};
const money=p=>p.price===null?'Not set':new Intl.NumberFormat('en-GB',{style:'currency',currency:p.currency||'GBP'}).format(p.price/100);
let catalogue=[],user=null,currentProduct=null,image='',uploading=false,dirty=false,loading=false;
async function api(url,options={}){const res=await fetch(url,{credentials:'same-origin',cache:'no-store',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...options.headers}});let data;try{data=await res.json();}catch{throw new Error('The server could not complete your request. Please try again.');}if(!res.ok){const e=new Error(data.error||'Something went wrong.');e.status=res.status;throw e;}return data;}
function notice(text){$('#notice').textContent=text;$('#notice').style.display='block';clearTimeout(window.noticeTimer);window.noticeTimer=setTimeout(()=>$('#notice').style.display='none',5000);}
function login(error=''){$('#root').innerHTML=`<div class="login"><section class="login-story"><a class="wordmark" href="/">TSOIE<small>BEAUTY · STUDIO</small></a><div><div class="eyebrow">A considered approach to beauty</div><h1>Behind every<br>beautiful detail.</h1><p>Your space to curate the collection, refine the details and bring the TSOIE experience to life.</p></div><p class="sub">TSOIE Beauty · Administration</p></section><section class="login-panel"><div class="login-box"><div class="eyebrow">Welcome to the studio</div><h2>Sign in to your space.</h2><p class="sub">Manage your collection and keep your storefront up to date.</p><form id="login-form"><label class="form-label" for="email">Email address</label><input class="input" id="email" name="email" type="email" autocomplete="username" value="admin@tsoiebeauty.com" required><label class="form-label" for="password">Password</label><div class="password-wrap"><input class="input" id="password" name="password" type="password" autocomplete="current-password" required><button type="button" id="show-password" aria-label="Show password">Show</button></div><div id="login-error" class="error" role="alert" ${error?'':'hidden'}>${esc(error)}</div><button class="button wide" type="submit" id="login-submit">Sign in to Studio <span>→</span></button></form><a class="back-link" href="/">← Back to the storefront</a></div></section></div>`;$('#show-password').onclick=()=>{const show=$('#password').type==='password';$('#password').type=show?'text':'password';$('#show-password').textContent=show?'Hide':'Show';};$('#login-form').onsubmit=signIn;}
async function signIn(event){event.preventDefault();const button=$('#login-submit');button.disabled=true;button.textContent='Signing in…';$('#login-error').hidden=true;try{user=await api('/api/session',{method:'POST',body:JSON.stringify({email:$('#email').value,password:$('#password').value})});await dashboard();}catch(e){$('#login-error').textContent=e.message;$('#login-error').hidden=false;}finally{if($('#login-submit')){$('#login-submit').disabled=false;$('#login-submit').textContent='Sign in to Studio →';}}}
async function signOut(){try{await api('/api/session',{method:'DELETE'});user=null;catalogue=[];login();}catch(e){notice(e.message);}}
async function dashboard(){
 $('#root').innerHTML=`<div class="layout"><aside class="sidebar"><a class="wordmark" href="/">TSOIE<small>BEAUTY · STUDIO</small></a><div class="nav-label">WORKSPACE</div><button class="nav-item" id="nav-products">${icons.box} Products</button><button class="nav-item nav-secondary" id="nav-orders">${icons.draft} Orders</button><div class="sidebar-help">A curated collection.<br>Every detail, in your hands.</div><div class="sidebar-bottom"><div class="account"><div class="avatar">TB</div><div><strong>TSOIE Administrator</strong><span>${esc(user.email)}</span></div></div><button class="account-settings" id="change-password">Change password</button><button class="signout">Sign out ↗</button></div></aside><section class="main"><header class="topbar"><div class="breadcrumbs">Studio <span>/</span> <strong>Products</strong></div><a class="live-link" href="/" target="_blank" rel="noopener"><span class="dot"></span> View storefront ↗</a></header><div class="content"><div class="page-title"><div><h1>Your collection</h1><p class="sub">Thoughtfully curated. Beautifully presented.</p></div><button class="button" id="add-product">＋ Add product</button></div><div id="dashboard-error" class="error error-banner" role="alert" hidden></div><div class="stats" id="stats"></div><section class="catalog"><div class="catalog-top"><h2>All products <span class="count" id="count">—</span></h2><div class="tools"><div class="search-wrap">${icons.search}<input class="input" type="search" id="search" placeholder="Search your collection…" aria-label="Search products"></div><select class="input" id="status-filter" aria-label="Filter by status"><option value="all">All statuses</option><option value="active">Active</option><option value="draft">Draft</option></select></div></div><div class="table-scroll"><table><thead><tr><th>Product</th><th>Status</th><th>Category</th><th>Price</th><th>Inventory</th><th><span class="muted">Manage</span></th></tr></thead><tbody id="products"><tr><td colspan="6" class="empty">Loading your collection…</td></tr></tbody></table></div><div class="catalog-footer"><span id="shown-count">Loading…</span><span class="sync-note"><span class="dot"></span> Saved changes sync to the storefront</span><button class="refresh" id="refresh">↻ Refresh</button></div></section><div class="bottom-note">The details make the difference. Changes are saved securely and shared across your storefront.</div><div class="mobile-account">${esc(user.email)} · <button id="mobile-password">Change password</button> · <button id="mobile-signout">Sign out</button></div></div></section></div>`;
 $('#nav-products').onclick=dashboard;$('#nav-orders').onclick=()=>showOrders(0);$('#change-password').onclick=openPassword;$('#mobile-password').onclick=openPassword;$('.signout').onclick=signOut;$('#mobile-signout').onclick=signOut;$('#add-product').onclick=()=>openEditor();$('#search').oninput=draw;$('#status-filter').onchange=draw;$('#refresh').onclick=refresh;await refresh();
}
async function refresh(){if(loading)return;loading=true;$('#refresh').disabled=true;try{const result=await api('/api/products?admin=1');catalogue=result.products;$('#dashboard-error').hidden=true;draw();}catch(e){if(e.status===401){login('Your session has expired. Please sign in again.');return;}$('#dashboard-error').textContent=e.message;$('#dashboard-error').hidden=false;$('#products').innerHTML='<tr><td colspan="6" class="empty">Could not load your collection. Please try Refresh.</td></tr>';}finally{loading=false;if($('#refresh'))$('#refresh').disabled=false;}}
function draw(){
 const active=catalogue.filter(p=>p.published).length,unpriced=catalogue.filter(p=>p.price===null).length;
 $('#stats').innerHTML=[[catalogue.length,'Total products','Your complete collection','box'],[active,'Active products','Visible on the storefront','check'],[catalogue.length-active,'Draft products','Saved for a future reveal','draft'],[unpriced,'Awaiting a price','Ready for your final details','price']].map(x=>`<article class="stat"><div class="stat-label">${x[1]} ${icons[x[3]]}</div><div class="stat-number">${x[0]}</div><div class="stat-note">${x[2]}</div></article>`).join('');
 const query=$('#search').value.toLowerCase(),status=$('#status-filter').value;const list=catalogue.filter(p=>(p.name+' '+p.category).toLowerCase().includes(query)&&(status==='all'||p.published===(status==='active')));
 $('#count').textContent=catalogue.length;$('#shown-count').textContent=`Showing ${list.length} of ${catalogue.length} products`;
 $('#products').innerHTML=list.length?list.map(p=>`<tr><td><div class="product-cell"><img src="${esc(p.image)}" alt="${esc(p.name)}"><div><strong>${esc(p.name)}</strong><small>${esc(p.shortDescription||'TSOIE Beauty')}</small></div></div></td><td><span class="status ${p.published?'':'draft'}">${p.published?'Active':'Draft'}</span></td><td><span class="category">${esc(p.category)}</span></td><td><span class="${p.price===null?'price-empty':'price-value'}">${money(p)}</span></td><td><span class="category">${p.stock===null?'Not tracked':p.stock===0?'Out of stock':`${p.stock} available`}</span></td><td><button class="edit-button" data-edit="${esc(p.id)}" aria-label="Edit ${esc(p.name)}">Edit ↗</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No products match your search.</td></tr>';
 document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openEditor(catalogue.find(p=>p.id===b.dataset.edit)));
}
function openEditor(p){currentProduct=p?structuredClone(p):null;image=p?.image||'';dirty=false;uploading=false;
 $('#editor-content').innerHTML=`<form id="product-form"><header class="editor-header"><div><h2 id="editor-heading">${p?'Refine your product':'Add to the collection'}</h2><p class="sub">${p?'Every detail, considered.':'A new addition to the TSOIE story.'}</p></div><button type="button" class="close" id="close-editor" aria-label="Close editor">×</button></header><div class="editor-body"><section class="editor-col"><label class="form-label" for="product-name">Product name</label><input class="input" id="product-name" name="name" value="${esc(p?.name)}" placeholder="e.g. Signature Lip Colour" maxlength="120" required><div class="form-row"><div><label class="form-label" for="product-category">Category</label><select class="input" id="product-category" name="category">${['Lips','Complexion','Eyes','Sets'].map(c=>`<option ${c===p?.category?'selected':''}>${c}</option>`).join('')}</select></div><div><label class="form-label" for="product-badge">Product badge</label><select class="input" id="product-badge" name="badge">${['','NEW','BESTSELLER','LIMITED'].map(v=>`<option value="${v}" ${v===p?.badge?'selected':''}>${v||'No badge'}</option>`).join('')}</select></div></div><div class="form-row"><div><label class="form-label" for="product-price">Price · GBP (£)</label><input class="input" id="product-price" name="price" type="number" min="0" max="1000000" step="0.01" placeholder="Not set" value="${p?.price==null?'':(p.price/100).toFixed(2)}"><p class="field-hint">Leave blank until the price is confirmed.</p></div><div><label class="form-label" for="product-stock">Available stock</label><input class="input" id="product-stock" name="stock" type="number" min="0" max="1000000" step="1" placeholder="Not tracked" value="${p?.stock??''}"><p class="field-hint">Leave blank to skip stock tracking.</p></div></div><label class="form-label" for="product-short">Short description</label><input class="input" id="product-short" name="shortDescription" value="${esc(p?.shortDescription)}" placeholder="A few words about the finish or feel" maxlength="250"><label class="form-label" for="product-description">Product description</label><textarea class="input" id="product-description" name="description" maxlength="5000" rows="5" placeholder="Introduce the formula, finish and experience…">${esc(p?.description)}</textarea></section><section class="editor-col media"><div><label class="form-label" for="image-file">Product imagery</label><div class="upload-preview" id="image-preview">${image?`<img src="${esc(image)}" alt="Product image preview">`:'<div class="placeholder">Your product,<br>beautifully presented.<br>＋ Add an image</div>'}</div><input class="upload-input" id="image-file" type="file" accept="image/jpeg,image/png,image/webp"><label for="image-file" class="button secondary upload-control" id="upload-label">↑ ${image?'Replace image':'Upload image'}</label><p class="upload-hint">JPG, PNG or WebP · Up to 3 MB<br>Images are optimised automatically.</p></div><div class="publish-box"><label><input id="product-published" name="published" type="checkbox" ${p?.published!==false?'checked':''}> Active on storefront</label><p>Active products appear in the shop as soon as you save. Turn off to keep this product as a draft.</p></div></section></div><div class="error editor-error" id="editor-error" role="alert" hidden></div><footer class="editor-footer"><span class="save-note">${p?'<button type="button" class="delete-product" id="delete-product">Delete product</button>':'Saved changes go directly to your storefront.'}</span><div class="actions"><button type="button" class="button secondary" id="cancel-editor">Cancel</button><button type="submit" class="button" id="save-product">${p?'Save changes':'Create product'} →</button></div></footer></form>`;
 $('#close-editor').onclick=closeEditor;$('#cancel-editor').onclick=closeEditor;$('#product-form').oninput=()=>{dirty=true;};$('#product-form').onsubmit=saveProduct;$('#image-file').onchange=uploadImage;$('#editor').showModal();$('#product-name').focus();if(p)$('#delete-product').onclick=deleteProduct;
}
function closeEditor(){if(uploading)return notice('Please wait for the upload to finish.');if(dirty&&!confirm('Discard your unsaved changes?'))return;$('#editor').close();}
$('#editor').addEventListener('cancel',e=>{e.preventDefault();closeEditor();});
async function uploadImage(){const file=$('#image-file').files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>3*1024*1024){notice('Choose a JPG, PNG or WebP image smaller than 3 MB.');return;}uploading=true;$('#save-product').disabled=true;$('#upload-label').textContent='Uploading & optimising…';$('#image-preview').classList.add('image-uploading');$('#editor-error').hidden=true;
 try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(new Error('Could not read this image.'));reader.readAsDataURL(file);});const result=await api('/api/upload',{method:'POST',body:JSON.stringify({data})});image=result.image;$('#image-preview').innerHTML=`<img src="${esc(image)}" alt="Product image preview">`;dirty=true;notice('Image uploaded. Save the product to publish it.');}catch(e){$('#editor-error').hidden=false;$('#editor-error').textContent=e.message;}finally{uploading=false;$('#save-product').disabled=false;$('#upload-label').textContent='↑ Replace image';$('#image-preview').classList.remove('image-uploading');$('#image-file').value='';}}
async function saveProduct(event){event.preventDefault();if(uploading)return;const form=new FormData(event.target);if(!image){$('#editor-error').hidden=false;$('#editor-error').textContent='Please upload an image for this product.';return;}
 const priceText=String(form.get('price')).trim();const price=priceText===''?null:Math.round(Number(priceText)*100);const stockText=String(form.get('stock')).trim();
 const data={name:form.get('name'),category:form.get('category'),badge:form.get('badge'),price,stock:stockText===''?null:Number(stockText),shortDescription:form.get('shortDescription'),description:form.get('description'),published:form.get('published')==='on',image,...(currentProduct?{id:currentProduct.id,revision:currentProduct.revision}:{})};
 const save=$('#save-product');save.disabled=true;save.textContent='Saving…';$('#editor-error').hidden=true;
 try{const result=await api('/api/products',{method:currentProduct?'PUT':'POST',body:JSON.stringify(data)});const i=catalogue.findIndex(p=>p.id===result.product.id);if(i>=0)catalogue[i]=result.product;else catalogue.unshift(result.product);dirty=false;$('#editor').close();draw();notice(result.product.published?'Saved. Your storefront is up to date.':'Draft saved. This product is hidden from the storefront.');localStorage.setItem('tsoie-catalog-updated',String(Date.now()));}catch(e){$('#editor-error').hidden=false;$('#editor-error').textContent=e.message;if(e.status===409){await refresh();}}finally{save.disabled=false;save.textContent=currentProduct?'Save changes →':'Create product →';}
}
window.addEventListener('beforeunload',e=>{if(dirty&&$('#editor').open){e.preventDefault();e.returnValue='';}});
try{user=await api('/api/session');await dashboard();}catch(e){login(e.status===401?'':e.message);}

async function deleteProduct(){if(uploading)return; if(!confirm('Delete this product from the catalogue and storefront? This cannot be undone.'))return;$('#delete-product').disabled=true;try{await api('/api/products',{method:'DELETE',body:JSON.stringify({id:currentProduct.id,revision:currentProduct.revision})});catalogue=catalogue.filter(p=>p.id!==currentProduct.id);dirty=false;$('#editor').close();draw();localStorage.setItem('tsoie-catalog-updated',String(Date.now()));notice('Product deleted.');}catch(e){$('#editor-error').hidden=false;$('#editor-error').textContent=e.message;$('#delete-product').disabled=false;}}

function openPassword(){
 $('#password-content').innerHTML=`<form id="password-form"><header class="editor-header"><div><h2 id="password-heading">Change password</h2><p class="sub">Keep access to your studio secure.</p></div><button type="button" class="close" id="password-close" aria-label="Close change password">×</button></header><div class="password-body"><label class="form-label" for="current-password">Current password</label><input class="input" id="current-password" type="password" autocomplete="current-password" maxlength="256" required><label class="form-label" for="new-password">New password</label><input class="input" id="new-password" type="password" autocomplete="new-password" minlength="12" maxlength="256" required><p class="field-hint">Use at least 12 characters. After saving, sign in again with your new password. All existing sessions will be signed out.</p><label class="password-reveal"><input type="checkbox" id="password-reveal"> Show passwords</label><div class="error" id="password-error" role="alert" hidden></div></div><footer class="editor-footer"><button type="button" class="button secondary" id="password-cancel">Cancel</button><button type="submit" class="button" id="password-save">Update password →</button></footer></form>`;
 const dialog=$('#password-dialog');const close=()=>{if(!$('#password-save').disabled)dialog.close();};$('#password-close').onclick=close;$('#password-cancel').onclick=close;dialog.oncancel=e=>{if($('#password-save').disabled)e.preventDefault();};$('#password-reveal').onchange=e=>{for(const id of ['current-password','new-password'])$('#'+id).type=e.target.checked?'text':'password';};$('#password-form').onsubmit=changePassword;dialog.showModal();$('#current-password').focus();
}
async function changePassword(event){
 event.preventDefault();const save=$('#password-save');save.disabled=true;save.textContent='Updating…';$('#password-error').hidden=true;
 try{await api('/api/password',{method:'POST',body:JSON.stringify({currentPassword:$('#current-password').value,newPassword:$('#new-password').value})});$('#password-form').reset();$('#password-dialog').close();user=null;catalogue=[];login();notice('Password changed. Sign in with your new password.');}
 catch(e){$('#password-error').textContent=e.message;$('#password-error').hidden=false;}
 finally{save.disabled=false;save.textContent='Update password →';}
}

let orderPage=[];
async function showOrders(page=0){
 document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('nav-secondary',n.id!=='nav-orders'));
 $('.breadcrumbs').innerHTML='Studio <span>/</span> <strong>Orders</strong>';
 $('.content').innerHTML=`<div class="page-title"><div><h1>Your orders</h1><p class="sub">Payments confirmed securely by Stripe.</p></div><button class="button secondary" id="refresh-orders">↻ Refresh</button></div><div id="order-setup" class="payment-setup"></div><div class="catalog space-orders"><div class="table-scroll"><table><thead><tr><th>Order</th><th>Customer</th><th>Payment</th><th>Total</th><th>Placed</th><th>Manage</th></tr></thead><tbody id="orders-table"><tr><td colspan="6" class="empty">Loading orders…</td></tr></tbody></table></div><div class="catalog-footer"><button id="orders-prev" class="refresh" ${page===0?'disabled':''}>← Previous</button><span>Page ${page+1}</span><button id="orders-next" class="refresh">Next →</button></div></div>`;
 $('#refresh-orders').onclick=()=>showOrders(page);$('#orders-prev').onclick=()=>showOrders(page-1);$('#orders-next').onclick=()=>showOrders(page+1);
 try{
  const data=await api('/api/orders?page='+page);orderPage=data.orders;$('#orders-next').disabled=!data.hasMore;
  $('#order-setup').textContent=data.paymentSetup.ready?(data.paymentSetup.live?'Live Stripe payments are enabled.':'Stripe test mode: these payments do not move real money or create shipments.'):'Payment setup is incomplete. Missing: '+data.paymentSetup.missing.join(', ');
  $('#orders-table').innerHTML=orderPage.length?orderPage.map(o=>`<tr><td><strong>${esc(o.number)}</strong><div class="small-order">${o.live?'Live':'Test mode'}</div></td><td>${esc(o.customer?.name||'Awaiting checkout')}<div class="small-order">${esc(o.customer?.email||'')}</div></td><td><span class="status ${o.status==='paid'?'':'draft'}">${esc(o.status)}</span></td><td>${new Intl.NumberFormat('en-GB',{style:'currency',currency:o.currency}).format(o.total/100)}</td><td>${new Date(o.createdAt).toLocaleDateString('en-GB')}</td><td><button class="edit-button" data-order="${esc(o.id)}">View details ↗</button></td></tr>`).join(''):'<tr><td colspan="6" class="empty">No orders yet. Completed payments will appear here.</td></tr>';
  document.querySelectorAll('[data-order]').forEach(b=>b.onclick=()=>showOrder(orderPage.find(o=>o.id===b.dataset.order)));
 }catch(e){if(e.status===401)return login('Please sign in again.');$('#orders-table').innerHTML=`<tr><td colspan="6" class="empty">${esc(e.message)}</td></tr>`;}
}
function showOrder(order){
 dirty=false;uploading=false;const format=n=>new Intl.NumberFormat('en-GB',{style:'currency',currency:order.currency}).format(n/100);const shipping=order.customer?.shipping;const address=shipping?.address;
 $('#editor-content').innerHTML=`<header class="editor-header"><div><h2 id="editor-heading">${esc(order.number)}</h2><p class="sub">${order.live?'Live order':'Test order — do not ship'} · ${esc(order.status)}</p></div><button class="close" id="close-order" aria-label="Close order">×</button></header><div class="password-body"><h3 class="order-section">Products</h3>${order.items.map(i=>`<p class="sub">${esc(i.name)} · Sample ${i.shade+1} × ${i.quantity} <strong>${format(i.unitAmount*i.quantity)}</strong></p>`).join('')}<p class="sub">Delivery: ${format(order.shipping)}<br><strong>Total: ${format(order.total)}</strong></p>${order.presentment&&order.presentment.currency!==order.currency?`<p class="sub">Customer paid in ${esc(order.presentment.currency)}: ${convertedAmount(order.presentment.amount,order.presentment.currency)}</p>`:''}<h3 class="order-section">Customer & delivery</h3><p class="sub">${esc(order.customer?.name||'Not yet collected')}<br>${esc(order.customer?.email||'')}</p>${address?`<p class="sub">${[shipping.name,address.line1,address.line2,address.city,address.state,address.postal_code,address.country].filter(Boolean).map(esc).join('<br>')}</p>`:''}${order.paymentIntentId?`<a class="button secondary" href="https://dashboard.stripe.com/${order.live?'':'test/'}payments/${encodeURIComponent(order.paymentIntentId)}" target="_blank" rel="noopener">View payment in Stripe ↗</a>`:''}</div>`;
 $('#close-order').onclick=()=>$('#editor').close();$('#editor').showModal();
}
